def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x, lb, ub):
        return np.clip(x, lb, ub)

    def generate_initial_simplex(rng, dim, lb, ub):
        x = lb + (ub - lb) * rng.rand(dim)
        simplex = np.vstack((x, x + 0.1 * rng.randn(dim)))
        return simplex

    initial_simplex = generate_initial_simplex(rng, dim, lb, ub)

    for _ in range(budget):
        centroid = np.mean(initial_simplex, axis=0)
        y = clip(centroid, lb, ub)
        initial_simplex = np.vstack((initial_simplex, y))

        # Compute simplex sorted along the objective function value
        sorted_indices = np.argsort([func(x) for x in initial_simplex])
        sorted_simplex = initial_simplex[sorted_indices]

        # Reflection step
        r = 2 * centroid - sorted_simplex[-1]
        yr = func(clip(r, lb, ub))
        if yr < func(sorted_simplex[-1]):
            initial_simplex[-1] = r

        # Expansion step
        if yr < func(sorted_simplex[0]) and yr < func(sorted_simplex[-2]):
            x_expansion = 2 * r - centroid
            y_expansion = func(clip(x_expansion, lb, ub))
            if y_expansion < yr:
                initial_simplex[-1] = x_expansion

        # Contraction step
        else:
            for i in range(len(sorted_simplex) - 1):
                xi = sorted_simplex[i]
                r_contraction = centroid + (xi - centroid) / 2
                yr_contraction = func(clip(r_contraction, lb, ub))
                if yr_contraction < func(xi):
                    initial_simplex[i] = r_contraction

    best_x = initial_simplex[np.argmin([func(x) for x in initial_simplex])]
    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    D = dim
    sigma = 0.5
    lambda_ = 1
    mu = D / 2
    cmu = np.zeros(D)
    c1 = 1 + 2 / (D * (D + 4))
    c2 = 1 - 1 / (D + 3)

    x_best = rng.uniform(lb, ub, size=D)
    f_best = func(x_best)

    for t in range(budget):
        x_cand = np.zeros((lambda_, D))

        for i in range(lambda_):
            for j in range(D):
                csigma = rng.normal(0, 1) * sigma
                ccmu = cmu.copy()
                ccmu[j] += csigma

                x_cand[i, j] = clip(x_best[j] + ccmu[j])

        f_cand = np.array([func(clip(x)) for x in x_cand])

        idx_sorted = np.argsort(f_cand)
        f_cand_sorted = f_cand[idx_sorted]
        x_cand_sorted = x_cand[idx_sorted]

        if t < budget - 1:
            sigma *= 0.5 * c2 + rng.normal(0, 0.01)

        for i in range(lambda_):
            if i < mu:
                cmu += (x_cand_sorted[i] - x_best) / lambda_
            else:
                cmu = c1 * cmu + (x_cand_sorted[i] - x_best) / lambda_

        sigma_new = np.sqrt(np.dot(cmu, cmu))

        if f_cand_sorted[0] < f_best or rng.uniform(0, 1) < np.exp(-(f_cand_sorted[0] - f_best) / (2 * sigma_new**2)):
            x_best = clip(x_cand_sorted[0])
            f_best = f_cand_sorted[0]
        elif rng.uniform(0, 1) < c1:
            idx_parent = np.random.choice(np.arange(lambda_), size=lambda_, replace=False)
            for i in range(lambda_):
                if idx_parent[i] == 0 or (f_cand_sorted[idx_parent[i]] > f_best and rng.uniform(0, 1) < np.exp(-(f_cand_sorted[idx_parent[i]] - f_best) / (2 * sigma_new**2))):
                    x_best = clip(x_cand_sorted[idx_parent[i]])
                    f_best = f_cand_sorted[idx_parent[i]]

    return x_best

